//! Texture coordinates: read from the file's maps, fitted onto the holes of
//! a mapped face, or generated by projection when a texture asks for it.

use glam::DVec3;
use std::collections::HashMap;
use tessifc_mesh::Mesh64;

/// Give the face just appended to `mesh` (its `outer` ring and `holes`,
/// starting at vertex `base`) its texture coordinates.
///
/// The outer ring takes `outer_uvs` when there are as many as corners; the
/// holes take the affine map the outer ring defines, since a texture on a
/// plane is affine. A face without coordinates on a mesh that has them gets
/// zeros, and a mesh without any stays without.
pub(crate) fn push_face_uvs(
    mesh: &mut Mesh64,
    base: usize,
    outer: &[DVec3],
    holes: &[Vec<DVec3>],
    outer_uvs: Option<&[[f32; 2]]>,
) {
    let given = outer_uvs.filter(|uvs| uvs.len() == outer.len());
    if given.is_none() && mesh.uvs.is_empty() {
        return;
    }
    mesh.uvs.resize(base, [0.0, 0.0]);
    match given {
        Some(uvs) => {
            mesh.uvs.extend_from_slice(uvs);
            let fit = affine_fit(outer, uvs);
            for hole in holes {
                for point in hole {
                    mesh.uvs
                        .push(fit.as_ref().map_or([0.0, 0.0], |fit| fit(*point)));
                }
            }
        }
        None => {
            let count = outer.len() + holes.iter().map(Vec::len).sum::<usize>();
            mesh.uvs.extend(std::iter::repeat_n([0.0, 0.0], count));
        }
    }
}

/// The affine map from points of a face's plane to its texture coordinates,
/// from three corners that are not collinear; `None` when there are none.
fn affine_fit(outer: &[DVec3], uvs: &[[f32; 2]]) -> Option<impl Fn(DVec3) -> [f32; 2]> {
    let a = *outer.first()?;
    let mut best: Option<(usize, usize, f64)> = None;
    for i in 1..outer.len() {
        for j in i + 1..outer.len() {
            let area = (outer[i] - a).cross(outer[j] - a).length();
            if best.is_none_or(|(_, _, known)| area > known) {
                best = Some((i, j, area));
            }
        }
    }
    let (i, j, area) = best?;
    if area.is_nan() || area <= 1e-18 {
        return None;
    }
    let (e1, e2) = (outer[i] - a, outer[j] - a);
    // Solve the 2x2 system for the plane coordinates of a point in the basis (e1, e2).
    let (g11, g12, g22) = (e1.dot(e1), e1.dot(e2), e2.dot(e2));
    let det = g11 * g22 - g12 * g12;
    if det.is_nan() || det.abs() <= 1e-30 {
        return None;
    }
    let (ua, ui, uj) = (uvs[0], uvs[i], uvs[j]);
    Some(move |point: DVec3| {
        let d = point - a;
        let (b1, b2) = (d.dot(e1), d.dot(e2));
        let s = (b1 * g22 - b2 * g12) / det;
        let t = (b2 * g11 - b1 * g12) / det;
        [
            ua[0] + (ui[0] - ua[0]) * s as f32 + (uj[0] - ua[0]) * t as f32,
            ua[1] + (ui[1] - ua[1]) * s as f32 + (uj[1] - ua[1]) * t as f32,
        ]
    })
}

/// Generate coordinates by projecting every triangle onto the plane its
/// normal faces most: the `COORD` generator, in the mesh's own metres from
/// the corner of its bounding box. A vertex shared by triangles facing
/// different axes is split, since it needs a coordinate per axis.
pub(crate) fn generate_planar_uvs(mesh: &mut Mesh64) {
    let Some((low, _)) = mesh.bounds() else {
        return;
    };
    let vertex_count = mesh.positions.len();
    let mut split: HashMap<(u32, u8), u32> = HashMap::with_capacity(vertex_count);
    let mut positions: Vec<DVec3> = Vec::with_capacity(vertex_count);
    let mut uvs: Vec<[f32; 2]> = Vec::with_capacity(vertex_count);
    let mut indices: Vec<u32> = Vec::with_capacity(mesh.indices.len());
    for triangle in mesh.indices.chunks_exact(3) {
        let (Some(&a), Some(&b), Some(&c)) = (
            mesh.positions.get(triangle[0] as usize),
            mesh.positions.get(triangle[1] as usize),
            mesh.positions.get(triangle[2] as usize),
        ) else {
            continue;
        };
        let normal = (b - a).cross(c - a).abs();
        let axis: u8 = if normal.x >= normal.y && normal.x >= normal.z {
            0
        } else if normal.y >= normal.z {
            1
        } else {
            2
        };
        for &corner in triangle {
            let index = *split.entry((corner, axis)).or_insert_with(|| {
                let point = mesh.positions[corner as usize];
                let local = point - low;
                let uv = match axis {
                    0 => [local.y as f32, local.z as f32],
                    1 => [local.x as f32, local.z as f32],
                    _ => [local.x as f32, local.y as f32],
                };
                positions.push(point);
                uvs.push(uv);
                (positions.len() - 1) as u32
            });
            indices.push(index);
        }
    }
    mesh.positions = positions;
    mesh.uvs = uvs;
    mesh.indices = indices;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_hole_takes_the_affine_map_of_its_outer_ring() {
        let outer = vec![
            DVec3::ZERO,
            DVec3::new(2.0, 0.0, 0.0),
            DVec3::new(2.0, 1.0, 0.0),
            DVec3::new(0.0, 1.0, 0.0),
        ];
        let hole = vec![
            DVec3::new(1.0, 0.5, 0.0),
            DVec3::new(1.5, 0.5, 0.0),
            DVec3::new(1.5, 0.75, 0.0),
        ];
        let mut mesh = Mesh64::new();
        mesh.positions.extend_from_slice(&outer);
        mesh.positions.extend_from_slice(&hole);
        push_face_uvs(
            &mut mesh,
            0,
            &outer,
            &[hole],
            Some(&[[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]),
        );
        assert_eq!(mesh.uvs.len(), 7);
        assert!((mesh.uvs[4][0] - 0.5).abs() < 1e-6 && (mesh.uvs[4][1] - 0.5).abs() < 1e-6);
        assert!((mesh.uvs[6][0] - 0.75).abs() < 1e-6 && (mesh.uvs[6][1] - 0.75).abs() < 1e-6);
    }

    #[test]
    fn a_face_without_a_map_pads_a_textured_mesh_and_leaves_a_plain_one() {
        let square = vec![
            DVec3::ZERO,
            DVec3::new(1.0, 0.0, 0.0),
            DVec3::new(1.0, 1.0, 0.0),
            DVec3::new(0.0, 1.0, 0.0),
        ];
        let mut plain = Mesh64::new();
        plain.positions.extend_from_slice(&square);
        push_face_uvs(&mut plain, 0, &square, &[], None);
        assert!(plain.uvs.is_empty());
        let mut textured = Mesh64::new();
        textured.positions.extend_from_slice(&square);
        push_face_uvs(&mut textured, 0, &square, &[], Some(&[[0.0; 2]; 4]));
        textured.positions.extend_from_slice(&square);
        push_face_uvs(&mut textured, 4, &square, &[], None);
        assert_eq!(textured.uvs.len(), 8);
    }

    #[test]
    fn a_cube_projected_by_axis_is_split_along_its_edges() {
        let mut mesh = crate::eval::primitives::box_mesh(DVec3::ZERO, DVec3::new(2.0, 1.0, 3.0));
        let triangles = mesh.triangle_count();
        generate_planar_uvs(&mut mesh);
        assert_eq!(mesh.triangle_count(), triangles);
        assert!(mesh.has_uvs());
        // Every corner meets three faces of different axes: 8 corners, 3 each.
        assert_eq!(mesh.positions.len(), 24);
        let widest = mesh
            .uvs
            .iter()
            .map(|uv| uv[0].max(uv[1]))
            .fold(0.0f32, f32::max);
        assert!((widest - 3.0).abs() < 1e-6, "{widest}");
    }
}
